"""Conditioning for every MiniMax-H3 task, built from diffusers' own pre-denoise blocks.

Tasks:

* ``t2v``    – text only;
* ``i2v``    – first frame (+ text);
* ``last2v`` – last frame (+ text);
* ``flf2v``  – first and last frame (+ text);
* ``ref2v``  – references: up to 9 images, 3 video clips (with their sound) and 3 audio clips (+ text), generated by
  the separate Ref2VA transformer.

The request-shaping logic — keyframe fitting, reference normalization (24 fps resampling, audio resampling, canvas
rules), the prompt presentation with its ``<Picture i>`` / ``<Video k>`` / ``<Audio j>`` labels and vision blocks,
keyframe / reference VAE encoding and the Ref2VA packed layout — is run with diffusers' blocks, so it is exactly the
released pipeline's. The one call those blocks make to the 32B conditioner is intercepted: it hands back the token
ids and the vision inputs, and TinyH3 encodes them with its own streamed text tower.
"""
from __future__ import annotations

import contextlib
import hashlib
import json
from dataclasses import dataclass, field
from pathlib import Path

import numpy as np
import torch

from ..store import Store

TASKS = {
    't2v': 'Текст → видео',
    'i2v': 'Первый кадр → видео',
    'last2v': 'Последний кадр → видео',
    'flf2v': 'Первый и последний кадр → видео',
    'ref2v': 'Референсы → видео',
}
KEYFRAME_TASKS = ('i2v', 'last2v', 'flf2v')


@dataclass
class Conditioning:
    task: str
    token_ids: list
    token_tags: torch.Tensor
    vision_inputs: dict
    condition_latents: list = field(default_factory=list)        # (1, C, t, h, w) normalized, per keyframe/reference
    audio_condition_latents: list = field(default_factory=list)  # (rows, 32) clean, per audio-bearing reference
    anchors: tuple = ()
    packed: tuple | None = None                                  # Ref2VA layout from diffusers
    media_digest: str = ''


def _match_size(width: int, height: int, target_area: int, multiple: int = 32) -> tuple[int, int]:
    """lightx2v 'match' policy: the reference keeps its aspect and at most the target's pixel area, never upscaled."""
    scale = min(1.0, (target_area / (width * height)) ** 0.5)
    return (max(multiple, round(width * scale / multiple) * multiple),
            max(multiple, round(height * scale / multiple) * multiple))


def _digest(paths) -> str:
    h = hashlib.sha256()
    for p in paths:
        if p:
            h.update(Path(p).read_bytes())
    return h.hexdigest()[:16]


class Conditioner:
    def __init__(self, store: Store, device):
        from diffusers.modular_pipelines.minimax_h3 import modular_blocks_minimax_h3 as mb
        from transformers import AutoProcessor, AutoTokenizer
        self.store = store
        self.device = torch.device(device)
        self.pipe = mb.MiniMaxH3Blocks().init_pipeline()
        tok_dir = store.path('tokenizer')
        proc_dir = store.path('processor') if store.path('processor').exists() else tok_dir
        self.pipe.update_components(tokenizer=AutoTokenizer.from_pretrained(str(tok_dir)),
                                    processor=AutoProcessor.from_pretrained(str(proc_dir)))
        self._vae = None
        self._audio_vae = None
        # the conditioner itself never runs here (its call is intercepted); the blocks only read its dtype
        from types import SimpleNamespace
        self.pipe.text_encoder = SimpleNamespace(dtype=torch.bfloat16, device=self.device)
        dev = self.device
        # The blocks place tensors on `_execution_device`, which diffusers infers from loaded components; with the
        # VAE decoder left on the meta device that inference is unreliable, so pin it.
        self.pipe.__class__ = type('TinyH3Pipeline', (type(self.pipe),),
                                   {'_execution_device': property(lambda _self: dev)})

    # -- lazily loaded encoders --------------------------------------------------------------------------------
    def vae(self):
        """The video VAE with only its encoder materialized (180M parameters; the 2.4B decoder stays on meta)."""
        if self._vae is None:
            from accelerate import init_empty_weights
            from diffusers import AutoencoderKLMiniMaxH3
            from safetensors.torch import load_file
            cfg = json.loads(self.store.path('vae/config.json').read_text())
            with init_empty_weights():
                vae = AutoencoderKLMiniMaxH3.from_config(cfg)
            weights = load_file(str(self.store.path('vae/encoder.safetensors')))
            vae.load_state_dict(weights, strict=False, assign=True)
            vae.encoder.to(self.device, torch.float32)
            vae.quant_conv.to(self.device, torch.float32)
            vae.eval()
            self._vae = vae
        return self._vae

    def audio_vae(self):
        if self._audio_vae is None:
            from diffusers import AutoencoderKLMiniMaxH3Audio
            self._audio_vae = AutoencoderKLMiniMaxH3Audio.from_pretrained(
                str(self.store.path('audio_vae')), torch_dtype=torch.float32).to(self.device).eval()
        return self._audio_vae

    # -- running diffusers blocks ------------------------------------------------------------------------------
    @contextlib.contextmanager
    def _captured_encoder(self, sink: dict):
        from diffusers.modular_pipelines.minimax_h3 import encoders

        def capture(text_encoder, processor, token_ids, vision_inputs=None, text_encoder_layer=50, device=None,
                    dtype=None):
            sink['token_ids'] = list(token_ids)
            sink['vision_inputs'] = dict(vision_inputs or {})
            return torch.zeros(1, len(token_ids), 1)

        original = encoders.get_qwen3vl_prompt_embeds
        encoders.get_qwen3vl_prompt_embeds = capture
        try:
            yield
        finally:
            encoders.get_qwen3vl_prompt_embeds = original

    def _run(self, blocks, **inputs):
        from diffusers.modular_pipelines import PipelineState
        state = PipelineState()
        for k, v in inputs.items():
            state.set(k, v)
        pipe = self.pipe
        for block in blocks:
            pipe, state = block(pipe, state)
        return state

    def _components_ready(self, need_vae=False, need_audio=False):
        updates = {}
        if need_vae:
            updates['vae'] = self.vae()
        if need_audio:
            updates['audio_vae'] = self.audio_vae()
        for k, v in updates.items():
            setattr(self.pipe, k, v)

    # -- tasks -------------------------------------------------------------------------------------------------
    @torch.no_grad()
    def prepare(self, task: str, prompt: str, height: int, width: int, num_frames: int, *, first=None, last=None,
                references=()) -> Conditioning:
        from diffusers.modular_pipelines.minimax_h3 import before_encoder, encoders, before_denoise
        if task not in TASKS:
            raise ValueError(f'неизвестная задача {task!r}')
        sink: dict = {}
        if task == 't2v':
            with self._captured_encoder(sink):
                state = self._run([encoders.MiniMaxH3TextEncoderStep()], prompt=prompt)
            return Conditioning(task, sink['token_ids'], state.get('text_token_tags'), {})

        if task in KEYFRAME_TASKS:
            image = _load_image(first) if task in ('i2v', 'flf2v') else None
            last_image = _load_image(last) if task in ('last2v', 'flf2v') else None
            if task in ('i2v', 'flf2v') and image is None or task in ('last2v', 'flf2v') and last_image is None:
                raise ValueError('для этой задачи нужен кадр')
            self._components_ready(need_vae=True)
            with self._captured_encoder(sink):
                state = self._run([before_encoder.MiniMaxH3ResizeStep(), encoders.MiniMaxH3FL2VATextEncoderStep(),
                                   encoders.MiniMaxH3KeyframeVaeEncoderStep()],
                                  prompt=prompt, image=image, last_image=last_image, height=height, width=width)
            return Conditioning(task, sink['token_ids'], state.get('text_token_tags'), sink['vision_inputs'],
                                condition_latents=list(state.get('condition_latents')),
                                anchors=tuple(state.get('keyframe_anchors')), media_digest=_digest([first, last]))

        # ref2v
        refs, originals = [], []
        for ref in references:
            obj, original = _load_reference(ref)
            refs.append(obj)
            originals.append(original)
        has_audio = any(r.has_audio for r in refs)
        self._components_ready(need_vae=True, need_audio=has_audio)
        with self._captured_encoder(sink):
            state = self._run([before_encoder.MiniMaxH3Ref2VASetupStep()], references=refs, height=height,
                              width=width, num_frames=num_frames)
            normalized = state.get('normalized_references')
            for i, (ref, original) in enumerate(zip(normalized, originals)):
                if ref.kind == 'image' and original is not None:  # 'match' sizing, from the original pixels
                    w, h = _match_size(original.width, original.height, height * width)
                    ref.image = original.resize((w, h), resample=3)
            state = self._run([encoders.MiniMaxH3Ref2VATextEncoderStep(),
                               encoders.MiniMaxH3Ref2VAReferenceEncoderStep(),
                               before_denoise.MiniMaxH3Ref2VAPrepareLayoutStep()],
                              prompt=prompt, normalized_references=normalized, height=height, width=width,
                              num_frames=num_frames)
        packed = tuple(state.get(k) for k in ('position_ids', 'token_tags', 'video_indices', 'audio_indices',
                                               'text_indices', 'num_condition_video_rows', 'num_condition_audio_rows'))
        return Conditioning(task, sink['token_ids'], state.get('text_token_tags'), sink['vision_inputs'],
                            condition_latents=list(state.get('condition_latents') or []),
                            audio_condition_latents=list(state.get('audio_condition_latents') or []),
                            packed=packed, media_digest=_digest([r.get('path') for r in references]))

    @torch.no_grad()
    def keyframe_latents(self, task: str, height: int, width: int, *, first=None, last=None) -> list:
        """Keyframe latents at another canvas size (the two-pass draft runs the first step smaller)."""
        from diffusers.modular_pipelines.minimax_h3 import before_encoder, encoders
        self._components_ready(need_vae=True)
        state = self._run([before_encoder.MiniMaxH3ResizeStep(), encoders.MiniMaxH3KeyframeVaeEncoderStep()],
                          image=_load_image(first) if task in ('i2v', 'flf2v') else None,
                          last_image=_load_image(last) if task in ('last2v', 'flf2v') else None,
                          height=height, width=width)
        return list(state.get('condition_latents'))


def _load_image(path):
    if path is None:
        return None
    from PIL import Image
    return Image.open(path).convert('RGB')


def _load_reference(ref: dict):
    from diffusers.modular_pipelines.minimax_h3.references import (
        MiniMaxH3AudioReference, MiniMaxH3ImageReference, MiniMaxH3VideoReference)
    kind, path = ref['kind'], ref['path']
    if kind == 'image':
        img = _load_image(path)
        return MiniMaxH3ImageReference(image=img), img
    if kind == 'video':
        return MiniMaxH3VideoReference.from_file(str(path)), None
    if kind == 'audio':
        return MiniMaxH3AudioReference.from_file(str(path)), None
    raise ValueError(f'неизвестный тип референса {kind!r}')
